import {
  isValidMicrosoftFoundryHostname,
  type MicrosoftFoundryHostname,
} from '@github-ui/copilot-byok/providers/microsoft-foundry'
import {FormControl, Stack, TextInput} from '@primer/react'
import {useId, useState} from 'react'
import * as z from 'zod'

import {modelIDSchema} from '../../../helpers/model-id-schema'
import styles from '../../AddEditDialog.module.css'
import {FormValidationNode} from '../../FormValidationNode'
import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'

const hostnameValidator = z.lazy(() =>
  z.custom<MicrosoftFoundryHostname>(
    isValidMicrosoftFoundryHostname,
    'Deployment URL must be a valid Microsoft Foundry endpoint',
  ),
)

export function azureFormSchemaPreprocessor(payload: Record<string, unknown>) {
  const providerData: Record<string, unknown> = {}
  if ('deployment_url' in payload && typeof payload.deployment_url === 'string') {
    const trimmed = payload.deployment_url.trim()
    // Always pass deployment_url (even if empty) so hostnameValidator can validate it
    providerData.deployment_url = trimmed
  }
  payload.provider_data = providerData
  return payload
}

export const azureFormSchema = {
  provider: z.literal('azureai'),
  // provider_data is optional to support editing (when only updating other fields like models)
  // but deployment_url within it is always validated when the object is present
  provider_data: z
    .object({
      deployment_url: z.string().pipe(hostnameValidator),
    })
    .optional(),
  models: z.array(
    z
      .object({
        id: z.number().optional(),
        slug: modelIDSchema.optional(),
        name: z.string().nullish(),
      })
      .refine(data => data.id || data.slug, {
        message: 'Either "id" or "slug" must be provided',
        path: ['id', 'slug'],
      }),
    'Please select a model',
  ),
} as const

export function AzureAIFields({
  apiKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
  org,
  onUpdateModel,
}: ProviderFieldProps<'azureai'>) {
  const id = useId()
  const [deploymentUrl, setDeploymentUrl] = useState((customKey && customKey?.deploymentUrl) || '')
  const deploymentUrlValidationId = `deployment_url-validation-${id}`
  const modelsValidationId = `models-validation-${id}`

  return (
    <>
      <FormControl required disabled={isPending}>
        <FormControl.Label>Deployment URL</FormControl.Label>
        <TextInput
          name="deployment_url"
          data-1p-ignore
          className="width-full"
          autoComplete="off"
          aria-describedby={deploymentUrlValidationId}
          defaultValue={deploymentUrl}
          onBlur={e => setDeploymentUrl(e.currentTarget.value)}
        />
        <FormValidationNode
          item={validation ? validation['provider_data.deployment_url'] : undefined}
          id={deploymentUrlValidationId}
        />
      </FormControl>

      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl disabled={isPending}>
          <FormControl.Label>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="azureai"
            apiKey={apiKey}
            customKeyId={customKey?.id}
            providerData={{provider: 'azureai', deploymentUrl}}
            isPending={isPending}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
            aria-describedby={modelsValidationId}
            canAddModels
            customKeyName={customKey?.name}
            org={org}
            onUpdateModel={onUpdateModel}
          />
          <FormValidationNode item={validation?.models} id={modelsValidationId} />
        </FormControl>
      </Stack.Item>
    </>
  )
}
