import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {getMaybeJSONErrorMessage} from '../helpers/extract-errors'
import type {UpdateCustomKeyPayload} from '../types'

export function updateCustomKeyMutationOptions({
  org,
  customKeyId,
}: {
  org: string
  customKeyId: number
}): UseMutationOptions<void, ResponseError, UpdateCustomKeyPayload> {
  return {
    async mutationFn(variables) {
      const req = await reactFetchJSON(`/organizations/${org}/settings/copilot/custom-keys/${customKeyId}`, {
        method: 'PUT',
        body: variables,
      })
      if (!req.ok) {
        const message = await getMaybeJSONErrorMessage(req)
        throw new ResponseError(message || 'Failed to update custom key', req)
      }
    },
  }
}
