import {registerDataRouterApp} from '@github-ui/react-core/register-app'

import {copilotByokSettingsAppBuilder} from './config/app-builder'
import {copilotByokSettingsLayoutRoute} from './routes/copilot-byok-settings-layout-route'
import {CopilotByokSettingsLayout} from './routes/CopiotByokSettingsLayout'
import {customModelsIndexRoute} from './routes/CustomModelsIndex/custom-models-index-route'
import {CustomModelsIndex} from './routes/CustomModelsIndex/CustomModelsIndex'

export const copilotByokSettingsApp = copilotByokSettingsAppBuilder.createDataRouterAppFromRoutes([
  copilotByokSettingsLayoutRoute.toRoute({
    Component: CopilotByokSettingsLayout,
    children: [
      customModelsIndexRoute.toRoute({
        Component: CustomModelsIndex,
      }),
    ],
  }),
])
registerDataRouterApp(copilotByokSettingsApp)
